package dev.differentenchant;

import dev.differentenchant.disenchant.*;
import dev.differentenchant.client.DisenchantScreen;
import java.util.*;
import java.nio.file.*;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;

/** Real OpenGL client: native placement, sneak assembly, selection packets and result pickup. */
public final class DisenchantClientGameTest implements FabricClientGameTest {
    private static final BlockPos CORE=new BlockPos(0,-59,0);
    private static void check(boolean v,String message){DisenchantGameTests.check(v,message);}
    private static void language(ClientGameTestContext c,String code){var future=c.computeOnClient(client->{client.getLanguageManager().setSelected(code);client.options.languageCode=code;return client.reloadResourcePacks();});c.waitFor(client->future.isDone()&&client.getOverlay()==null);c.waitTicks(3);}
    private static void cursor(ClientGameTestContext c,int x,int y){var a=c.computeOnClient(client->{double s=client.getWindow().getGuiScale();return new double[]{((client.screen.width-DisenchantMenu.WIDTH)/2+x)*s,((client.screen.height-DisenchantMenu.HEIGHT)/2+y)*s};});c.getInput().setCursorPos(a[0],a[1]);c.waitTick();}
    private static void click(ClientGameTestContext c,int x,int y){cursor(c,x,y);c.getInput().pressMouse(0);c.waitTicks(3);}
    private static void shift(ClientGameTestContext c,int x,int y){cursor(c,x,y);c.runOnClient(client->{var e=new net.minecraft.client.input.MouseButtonEvent((client.screen.width-DisenchantMenu.WIDTH)/2+x,(client.screen.height-DisenchantMenu.HEIGHT)/2+y,new net.minecraft.client.input.MouseButtonInfo(0,1));client.screen.mouseClicked(e,false);client.screen.mouseReleased(e);});c.waitTicks(3);}
    private static void shot(ClientGameTestContext c,String name){c.runOnClient(client->{client.getToastManager().clear();client.gui.getChat().clearMessages(true);});c.getInput().setCursorPos(1,1);c.waitTicks(8);c.takeScreenshot("disenchant-"+name);}
    private static void hover(ClientGameTestContext c,int x,int y,String name){cursor(c,x,y);c.waitTicks(6);c.takeScreenshot("disenchant-"+name);}
    private static void aim(ClientGameTestContext c,double x,double y,double z){var a=c.computeOnClient(client->{var e=client.player.getEyePosition();double dx=x-e.x,dy=y-e.y,dz=z-e.z;return new float[]{(float)(Math.toDegrees(Math.atan2(dz,dx))-90),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz)))};});c.getInput().lookAt(a[0],a[1]);}
    private static void open(ClientGameTestContext c){aim(c,.5,-58.5,.5);c.waitTicks(2);c.getInput().pressKey(o->o.keyUse);c.waitForScreen(DisenchantScreen.class);c.waitTicks(4);}
    private static void close(ClientGameTestContext c){c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(null);c.waitTicks(3);}
    private static Map<String,Integer> counts(TestSingleplayerContext w){return w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var all=new ArrayList<ItemStack>();for(int i=0;i<p.getInventory().getContainerSize();i++)all.add(p.getInventory().getItem(i));if(p.containerMenu instanceof DisenchantMenu m){all.add(m.getSlot(0).getItem());all.add(m.getSlot(1).getItem());}all.add(p.containerMenu.getCarried());for(var e:s.overworld().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(CORE).inflate(20)))all.add(e.getItem());var r=new TreeMap<String,Integer>();for(var a:all)if(!a.isEmpty())r.merge(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(a.getItem()).toString(),a.getCount(),Integer::sum);return r;});}
    @Override public void runTest(ClientGameTestContext c) {
        c.getInput().resizeWindow(1280,720);language(c,"en_us");TestWorldSave save;Map<String,Integer> saved;UUID machine;String gearData;
        var report=new StringBuilder();
        try(var w=c.worldBuilder().create()) {
            save=w.getWorldSave();w.getServer().runCommand("time set day");w.getServer().runCommand("weather clear");w.getServer().runCommand("difficulty peaceful");
            w.getServer().runOnServer(s->{var l=s.overworld();for(int i=0;i<9;i++)l.setBlockAndUpdate(DisenchantStructure.position(CORE,i),DisenchantStructure.original(i).defaultBlockState());var p=s.getPlayerList().getPlayers().getFirst();p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.getInventory().setSelectedSlot(0);p.getInventory().setItem(0,new ItemStack(DisenchantContent.CORE_ITEM));p.getInventory().setItem(9,DisenchantGameTests.fixture(l));p.getInventory().setItem(10,new ItemStack(Items.BOOK,5));var many=DisenchantGameTests.fixture(l);DisenchantGameTests.add(l,many,"minecraft:looting",3);DisenchantGameTests.add(l,many,"minecraft:fire_aspect",2);DisenchantGameTests.add(l,many,"minecraft:sweeping_edge",3);p.getInventory().setItem(11,many);p.giveExperienceLevels(40);p.teleportTo(.5,-60,-3.5);});
            c.waitTicks(5);aim(c,.5,-59.001,.5);c.waitTicks(3);c.getInput().pressKey(o->o.keyUse);c.waitTicks(5);
            w.getServer().runOnServer(s->{check(s.overworld().getBlockState(CORE).is(DisenchantContent.CORE),"native survival placed crafted core");for(int i=9;i<18;i++)if(i!=13)s.overworld().setBlockAndUpdate(DisenchantStructure.position(CORE,i),DisenchantStructure.original(i).defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(.5,-58,-.5);});
            c.waitTicks(4);aim(c,.5,-58.1,.5);c.getInput().holdKey(o->o.keyShift);c.waitTicks(2);c.getInput().pressKey(o->o.keyUse);c.waitTicks(4);c.getInput().releaseKey(o->o.keyShift);
            machine=w.getServer().computeOnServer(s->{var master=DisenchantStructure.controller(s.overworld(),CORE);check(master!=null,"native sneak-use assembled all18");return master.machineId();});
            w.getServer().runCommand("tp @a 4.5 -60 -4.5");c.waitTicks(3);aim(c,.5,-59,.5);shot(c,"01-assembled-exterior");
            w.getServer().runCommand("tp @a 0.5 -60 -2.5");c.waitTicks(3);open(c);shift(c,42,144);shift(c,60,144);c.waitTicks(3);
            c.runOnClient(client->{var m=(DisenchantMenu)client.player.containerMenu;check(m.choices().size()==3&&m.getSlot(0).getItem().is(Items.DIAMOND_SWORD)&&m.getSlot(1).getItem().getCount()==5&&m.getSlot(2).getItem().isEmpty(),"native shift inputs and only three ordinary choices; no automatic extraction");});shot(c,"02-multiple-enchantments-en");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;var original=m.getSlot(0).getItem();m.getSlot(0).set(p.getInventory().getItem(11));p.getInventory().setItem(11,original);m.broadcastChanges();});c.waitTicks(3);shot(c,"02b-six-choices-en");cursor(c,80,100);c.getInput().scroll(-2);c.waitTicks(2);c.getInput().scroll(-2);c.waitTicks(2);click(c,60,112);c.waitFor(client->client.player.containerMenu.getSlot(2).hasItem());c.runOnClient(client->check(DisenchantGameTests.rank(client.player.containerMenu.getSlot(2).getItem(),"minecraft:unbreaking")==2,"native scroll and last row select unbreaking III -> II"));hover(c,194,42,"02c-scrolled-last-choice-en");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;var many=m.getSlot(0).getItem();m.getSlot(0).set(p.getInventory().getItem(11));p.getInventory().setItem(11,many);m.broadcastChanges();});c.waitTicks(3);
            click(c,65,84);c.waitFor(client->client.player.containerMenu.getSlot(2).hasItem()); // Sorted registry IDs: mending, sharpness, unbreaking.
            c.runOnClient(client->check(DisenchantGameTests.rank(client.player.containerMenu.getSlot(2).getItem(),"minecraft:sharpness")==4,"selected Sharpness V previews IV"));shot(c,"03-selected-preview-en");hover(c,194,42,"04-result-tooltip-en");hover(c,24,42,"05-curse-equipment-tooltip-en");
            click(c,194,42);c.waitFor(client->client.player.containerMenu.getCarried().is(Items.ENCHANTED_BOOK));w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;check(p.experienceLevel==34&&m.getSlot(1).getItem().getCount()==4&&DisenchantGameTests.rank(m.getSlot(0).getItem(),"minecraft:sharpness")==0&&m.getSlot(0).getItem().getDamageValue()==137,"direct mouse pickup pays once, preserves named damaged cursed sword");});c.waitFor(client->((DisenchantMenu)client.player.containerMenu).selection()==-1&&((DisenchantMenu)client.player.containerMenu).cost()==0);cursor(c,194,112);c.takeScreenshot("disenchant-06-direct-result-pickup");click(c,42,202);
            language(c,"zh_cn");c.waitTicks(3);shot(c,"07-remainder-zh");hover(c,24,42,"08-preserved-curse-tooltip-zh");click(c,60,84);c.waitFor(client->client.player.containerMenu.getSlot(2).hasItem());hover(c,194,42,"09-unbreaking-result-tooltip-zh");shift(c,194,42);
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;check(p.experienceLevel==30&&m.getSlot(1).getItem().getCount()==3&&m.choices().size()==1,"second extraction via native shift once");});click(c,60,68);c.waitFor(client->client.player.containerMenu.getSlot(2).hasItem());hover(c,194,42,"10-mending-I-preview-zh");shift(c,194,42);c.waitTicks(3);shot(c,"11-curse-only-no-selection-zh");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;check(p.experienceLevel==27&&m.choices().isEmpty()&&m.getSlot(2).getItem().isEmpty()&&DisenchantGameTests.rank(m.getSlot(0).getItem(),"minecraft:vanishing_curse")==1,"all ordinary extracted singly and curse left untouched");});hover(c,24,42,"12-curse-only-equipment-zh");
            // Disconnect with real inputs and a valid unclaimed preview, never transferring the preview.
            w.getServer().runOnServer(s->{var m=(DisenchantMenu)s.getPlayerList().getPlayers().getFirst().containerMenu;DisenchantGameTests.add(s.overworld(),m.getSlot(0).getItem(),"differentenchant:borrowed_flame",2);m.broadcastChanges();});c.waitTicks(3);click(c,60,68);c.waitFor(client->client.player.containerMenu.getSlot(2).hasItem()&&((DisenchantMenu)client.player.containerMenu).cost()==3);shot(c,"13-lost-enchantment-preview-zh");
            saved=counts(w);gearData=w.getServer().computeOnServer(s->{var stack=((DisenchantMenu)s.getPlayerList().getPlayers().getFirst().containerMenu).getSlot(0).getItem();return net.minecraft.world.item.ItemStack.CODEC.encodeStart(s.overworld().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE),stack).getOrThrow().toString();});
            report.append("Real Minecraft 26.1.2 OpenGL client: survival core placement, empty-hand sneak assembly, right-click GUI, native shift equipment/books, select Sharpness V -> IV, direct mouse result, exactly one book + six levels. Original damage/name/curse kept.\nNative Shift extracts Unbreaking III -> II (four levels), Mending I -> I (three levels). Curse-only remainder cannot select or extract. English/Chinese slot/gear/result tooltips. Lost Borrowed Flame II -> I preview.\n");
        }
        try(var w=save.open()) {
            c.waitTicks(5);check(saved.equals(counts(w)),"disk disconnect/reconnect inventory plus drops totals unchanged; display never returned");w.getServer().runOnServer(s->{check(machine.equals(DisenchantStructure.controller(s.overworld(),CORE).machineId()),"assembled18 identity survives actual chunk save/reload");var p=s.getPlayerList().getPlayers().getFirst();check(p.experienceLevel==27,"experience persisted");var items=new ArrayList<ItemStack>();for(int i=0;i<p.getInventory().getContainerSize();i++)items.add(p.getInventory().getItem(i));for(var e:s.overworld().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(CORE).inflate(20)))items.add(e.getItem());var gear=items.stream().filter(a->a.is(Items.DIAMOND_SWORD)&&DisenchantGameTests.rank(a,"differentenchant:borrowed_flame")==2).findFirst().orElseThrow();check(net.minecraft.world.item.ItemStack.CODEC.encodeStart(s.overworld().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE),gear).getOrThrow().toString().equals(gearData),"full original equipment components persist after disconnect");});aim(c,.5,-59,.5);shot(c,"14-disk-reconnected-structure");
            // Open again through any formed part and break a part while inputs are held in the session.
            w.getServer().runCommand("tp @a 0.5 -60 -2.5");c.waitTicks(3);open(c);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;for(int i=0;i<36;i++){var a=p.getInventory().getItem(i);if(a.is(Items.BOOK)){m.getSlot(1).set(a);p.getInventory().setItem(i,ItemStack.EMPTY);break;}}m.broadcastChanges();});c.waitTicks(2);var before=counts(w);w.getServer().runOnServer(s->s.overworld().destroyBlock(DisenchantStructure.position(CORE,9),false));c.waitForScreen(null);c.waitTicks(3);check(before.equals(counts(w)),"breaking machine closes real client menu, returns inputs once");shot(c,"15-dismantled-safe-return");report.append("Disconnect with unclaimed lost-book preview: actual disk reload preserves all real item totals, full gear components, XP27 and machine UUID. Breaking a loaded part auto-closes native client menu and returns inputs without item loss.\n");
        }
        try{var p=Path.of("../reports/disenchant/client.txt");Files.createDirectories(p.getParent());Files.writeString(p,report.toString());}catch(Exception e){throw new RuntimeException(e);}
    }
}
